.bfusion-license-badge{position:absolute;left:6px;bottom:6px;font:11px/1.3 "Segoe UI",system-ui,sans-serif;padding:3px 8px;border-radius:3px;z-index:10;pointer-events:none;}
.bfusion-license-badge--trial{background:rgba(232,97,26,.92);color:#fff;box-shadow:0 1px 3px rgba(0,0,0,.15);}
.bfusion-license-badge--licensed{background:transparent;color:#b0b0b0;box-shadow:none;}
.bfusion-license-badge em{opacity:.85;font-style:normal;}
.bfusion-trial-watermark{position:absolute;inset:0;display:flex;align-items:center;justify-content:center;pointer-events:none;z-index:5;}
.bfusion-trial-watermark__text{font:600 28px/1 "Segoe UI",system-ui,sans-serif;color:rgba(232,97,26,.20);letter-spacing:.15em;transform:rotate(-22deg);text-transform:uppercase;}
.bfusion-locked-overlay{position:absolute;inset:0;background:rgba(248,249,251,.96);backdrop-filter:saturate(0.3) blur(2px);display:flex;align-items:center;justify-content:center;z-index:9999;font-family:"Segoe UI",system-ui,sans-serif;color:#1f2937;}
.bfusion-locked-overlay__inner{text-align:center;padding:32px 48px 24px;max-width:480px;background:#fff;border-radius:8px;border-top:3px solid #E8611A;}
.bfusion-locked-overlay__logo{width:120px;max-width:35%;height:auto;margin:0 auto 20px;display:block;border-radius:16px;overflow:hidden;}
.bfusion-locked-overlay__lock{font-size:24px;color:#E8611A;margin-bottom:6px;}
.bfusion-locked-overlay__title{font-size:20px;font-weight:600;color:#0f172a;margin-bottom:8px;letter-spacing:.01em;}
.bfusion-locked-overlay__subtitle{font-size:13px;color:#475569;line-height:1.6;margin-bottom:16px;}
.bfusion-locked-overlay__cta{font-size:12px;color:#64748b;border-top:1px solid #f1f5f9;padding-top:12px;}
