content.css:
/* ========================================================================== */
/* BFUSION Critical Path Diagram — Structural Styles                         */
/* ========================================================================== */
.bfusion-root {
  width: 100%;
  height: 100%;
  overflow: hidden;
  font-family: "Segoe UI", wf_segoe-ui_normal, helvetica, arial, sans-serif;
  background-color: #FFFFFF;
  position: relative;
  display: flex;
  flex-direction: column;
}
.bfusion-root *,
.bfusion-root *:before,
.bfusion-root *:after {
  box-sizing: border-box;
}
/* ── Header bar (title + subtitle + info button) ── */
.cpd-header {
  display: flex;
  align-items: flex-start;
  gap: 8px;
  padding: 10px 16px 6px 16px;
  border-bottom: 1px solid #E5E7EB;
  background: linear-gradient(180deg, #FFFFFF 0%, #F8F9FB 100%);
  position: relative;
  flex: 0 0 auto;
}
.cpd-header__titles {
  flex: 1 1 auto;
  min-width: 0;
}
.cpd-header__title {
  font-weight: 700;
  color: #242424;
  letter-spacing: 0.1px;
  line-height: 1.2;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.cpd-header__subtitle {
  margin-top: 2px;
  color: #6C757D;
  font-weight: 400;
  line-height: 1.3;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.cpd-header__info {
  flex: 0 0 auto;
  width: 20px;
  height: 20px;
  border-radius: 50%;
  border: 1px solid #E5E7EB;
  background: #fff;
  color: #6C757D;
  font-style: italic;
  font-weight: 700;
  font-size: 11px;
  cursor: pointer;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  line-height: 1;
  padding: 0;
  transition: all 0.15s ease;
}
.cpd-header__info:hover {
  color: #fff;
  background: var(--cpd-accent, #E8612A);
  border-color: var(--cpd-accent, #E8612A);
  transform: scale(1.05);
}
.cpd-header__info-pop {
  position: absolute;
  top: calc(100% + 6px);
  right: 12px;
  z-index: 30;
  width: 300px;
  max-width: calc(100% - 24px);
  background: #fff;
  border: 1px solid #E5E7EB;
  border-radius: 8px;
  box-shadow: 0 8px 24px rgba(15, 23, 42, 0.12);
  padding: 12px 14px;
  color: #242424;
  line-height: 1.45;
  font-size: 11px;
}
.cpd-header__info-pop ul {
  margin: 8px 0 0 0;
  padding-left: 18px;
}
.cpd-header__info-pop ul li {
  margin: 3px 0;
  color: #6C757D;
}
.cpd-info-pop__title {
  font-weight: 700;
  color: #242424;
  margin-bottom: 4px;
}
.cpd-info-pop__desc {
  color: #6C757D;
}
/* ── Insight toggle strip (between chart and panel) ── */
.cpd-insight-strip {
  flex: 0 0 auto;
  width: 24px;
  background: #F8F9FB;
  border-left: 1px solid #E5E7EB;
  color: #6C757D;
  cursor: pointer;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 8px;
  user-select: none;
  transition: background 0.15s ease, color 0.15s ease;
}
.cpd-insight-strip__arrow {
  font-size: 11px;
  color: var(--cpd-accent, #E8612A);
  line-height: 1;
}
.cpd-insight-strip__label {
  writing-mode: vertical-rl;
  transform: rotate(180deg);
  letter-spacing: 2px;
  font-weight: 600;
  font-size: 9px;
  color: #6C757D;
  text-transform: uppercase;
}
.cpd-insight-strip:hover,
.cpd-insight-strip:focus {
  background: #FFFFFF;
  color: #242424;
  outline: none;
}
/* Insight panel visibility states */
.cpd-body--insight-collapsed .bfusion-insights-panel {
  display: none !important;
}
.cpd-body--insight-hidden .bfusion-insights-panel,
.cpd-body--insight-hidden .cpd-insight-strip {
  display: none !important;
}
/* ── Main layout: chart + insights panel side by side ── */
.bfusion-main-area {
  display: flex;
  width: 100%;
  flex: 1;
  min-height: 0;
  overflow: hidden;
}
.bfusion-chart-wrap {
  flex: 1;
  min-width: 0;
  height: 100%;
  overflow: hidden;
  display: block;
  background: #ffffff;
  position: relative;
}
.bfusion-chart-wrap::-webkit-scrollbar {
  width: 10px;
  height: 10px;
}
.bfusion-chart-wrap::-webkit-scrollbar-track {
  background: #f4f5f6;
}
.bfusion-chart-wrap::-webkit-scrollbar-thumb {
  background: #b0bec5;
  border-radius: 4px;
}
.bfusion-chart-wrap::-webkit-scrollbar-thumb:hover {
  background: #78909c;
}
.bfusion-chart-wrap svg {
  display: block;
  min-width: 100%;
  min-height: 100%;
}
/* CPD Node hover */
.cpd-node:hover rect:first-child {
  filter: drop-shadow(0 2px 6px rgba(0, 0, 0, 0.15));
}
/* ========================================================================== */
/* Insights Panel (right side)                                                */
/* ========================================================================== */
.bfusion-insights-panel {
  height: 100%;
  overflow-y: auto;
  overflow-x: hidden;
  background: #FAFBFC;
  border-left: 1px solid #E0E4E8;
  font-size: 11px;
  color: #333;
  line-height: 1.45;
}
.bfusion-insights-panel::-webkit-scrollbar {
  width: 6px;
}
.bfusion-insights-panel::-webkit-scrollbar-track {
  background: transparent;
}
.bfusion-insights-panel::-webkit-scrollbar-thumb {
  background: #CBD5E0;
  border-radius: 3px;
}
.bfusion-insights-panel::-webkit-scrollbar-thumb:hover {
  background: #A0AEC0;
}
.bfusion-ip-header {
  padding: 12px 14px 8px;
  border-bottom: 1px solid #E0E4E8;
}
.bfusion-ip-title {
  font-size: 13px;
  font-weight: 700;
  color: #1A202C;
  margin-bottom: 2px;
}
.bfusion-ip-subtitle {
  font-size: 10px;
  color: #A0AEC0;
}
.bfusion-ip-back {
  font-size: 10px;
  color: #1565C0;
  cursor: pointer;
  margin-bottom: 6px;
  font-weight: 500;
}
.bfusion-ip-back:hover {
  text-decoration: underline;
}
.bfusion-ip-badge {
  display: inline-block;
  margin-top: 6px;
  padding: 2px 8px;
  border-radius: 3px;
  font-size: 9.5px;
  font-weight: 600;
  color: #fff;
  letter-spacing: 0.3px;
}
.bfusion-ip-section {
  padding: 10px 14px;
  border-bottom: 1px solid #EDF0F4;
}
.bfusion-ip-section-title {
  font-size: 10px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.6px;
  margin-bottom: 8px;
}
.bfusion-ip-metric {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 2px 0;
  gap: 6px;
}
.bfusion-ip-metric span:first-child {
  color: #555;
}
/* CPM 3x2 grid */
.bfusion-ip-cpm-grid {
  display: grid;
  grid-template-columns: 1fr 1fr 1fr;
  gap: 4px;
  margin-bottom: 8px;
}
.bfusion-ip-cpm-cell {
  text-align: center;
  background: #fff;
  border: 1px solid #E0E4E8;
  border-radius: 4px;
  padding: 4px 2px;
}
.bfusion-ip-cpm-val {
  font-size: 14px;
  font-weight: 700;
}
.bfusion-ip-cpm-lbl {
  font-size: 8.5px;
  color: #A0AEC0;
  text-transform: uppercase;
  letter-spacing: 0.5px;
}
/* Progress bar in insights */
.bfusion-ip-progress-bar {
  width: 100%;
  height: 6px;
  background: #E2E8F0;
  border-radius: 3px;
  overflow: hidden;
  margin-bottom: 4px;
}
.bfusion-ip-progress-fill {
  height: 100%;
  border-radius: 3px;
  transition: width 0.3s ease;
}
.bfusion-ip-progress-label {
  font-size: 10px;
  color: #718096;
  text-align: right;
  margin-bottom: 4px;
}
/* Float distribution bars */
.bfusion-ip-bar-row {
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 2px 0;
}
.bfusion-ip-bar-label {
  font-size: 9.5px;
  color: #555;
  min-width: 70px;
  flex-shrink: 0;
}
.bfusion-ip-bar-track {
  flex: 1;
  height: 5px;
  background: #E2E8F0;
  border-radius: 2.5px;
  overflow: hidden;
}
.bfusion-ip-bar-fill {
  height: 100%;
  border-radius: 2.5px;
}
.bfusion-ip-bar-val {
  font-size: 10px;
  font-weight: 600;
  min-width: 20px;
  text-align: right;
}
/* Dependencies list in task view */
.bfusion-ip-dep-label {
  font-size: 9.5px;
  font-weight: 600;
  color: #718096;
  margin-top: 4px;
  margin-bottom: 2px;
}
.bfusion-ip-dep-item {
  font-size: 10px;
  color: #4A5568;
  padding: 1px 0 1px 6px;
  border-left: 2px solid #E2E8F0;
}
/* ========================================================================== */
/* Custom Tooltip (S-Curve style)                                             */
/* ========================================================================== */
.bfusion-tooltip {
  position: absolute;
  display: none;
  pointer-events: none;
  background: rgba(255, 255, 255, 0.97);
  border: 1px solid #ccc;
  border-radius: 6px;
  box-shadow: 0 3px 12px rgba(0, 0, 0, 0.12);
  padding: 0;
  font-family: "Segoe UI", wf_segoe-ui_normal, helvetica, arial, sans-serif;
  font-size: 11px;
  z-index: 999;
  max-width: 280px;
  min-width: 200px;
  line-height: 1.5;
  color: #333;
  overflow: hidden;
}
.bfusion-tt-header {
  padding: 8px 10px 6px;
  border-bottom: 1px solid #eee;
  margin-left: 0;
}
.bfusion-tt-title {
  font-weight: 600;
  font-size: 11.5px;
  color: #1A202C;
}
.bfusion-tt-resource {
  font-size: 10px;
  color: #A0AEC0;
  margin-top: 1px;
}
.bfusion-tt-section {
  padding: 6px 10px;
  border-bottom: 1px solid #f5f5f5;
}
.bfusion-tt-section:last-of-type {
  border-bottom: none;
}
.bfusion-tt-section-label {
  font-size: 9px;
  font-weight: 700;
  text-transform: uppercase;
  color: #A0AEC0;
  letter-spacing: 0.5px;
  margin-bottom: 3px;
}
.bfusion-tt-row {
  display: flex;
  justify-content: space-between;
  gap: 8px;
  padding: 1px 0;
}
.bfusion-tt-label {
  color: #555;
}
.bfusion-tt-badge {
  padding: 4px 10px;
  font-size: 9.5px;
  font-weight: 600;
  text-align: center;
  letter-spacing: 0.3px;
}
.bfusion-tt-badge--critical {
  background: rgba(229, 57, 53, 0.08);
  color: #E53935;
}
.bfusion-tt-badge--near {
  background: rgba(255, 143, 0, 0.08);
  color: #FF8F00;
}
/* ========================================================================== */
/* Responsive Landing Page Framework                                         */
/* ========================================================================== */
.bfusion-landing-wrap {
  width: 100%;
  height: 100%;
  flex: 1;
  min-height: 0;
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  background-color: #FFFFFF;
  overflow: auto;
}
.bfusion-landing {
  display: flex;
  flex-direction: column;
  align-items: center;
  max-width: 420px;
  padding: 20px;
  box-sizing: border-box;
  text-align: center;
}
.bfusion-landing__logo-container {
  width: 130px;
  height: 84px;
  display: flex;
  justify-content: center;
  align-items: center;
  background-color: #FF5500;
  border-radius: 12px;
  box-shadow: 0 3px 8px rgba(0, 0, 0, 0.08);
  margin-bottom: 24px;
  overflow: hidden;
}
.bfusion-landing__logo {
  width: 100%;
  height: 100%;
  object-fit: contain;
}
.bfusion-landing__text-container {
  display: flex;
  flex-direction: column;
  align-items: center;
  width: 100%;
}
.bfusion-landing__title {
  font-size: 15px;
  font-weight: 600;
  color: #242424;
  margin: 0 0 14px 0;
  padding: 0;
  line-height: 1.2;
}
.bfusion-landing__description {
  font-size: 11.5px;
  font-weight: 400;
  color: #666666;
  margin: 0;
  padding: 0;
  line-height: 1.5;
}
.bfusion-landing__description strong {
  font-weight: 600;
  color: #444444;
}
.bfusion-landing__separator {
  width: 60%;
  height: 1px;
  background-color: #EAEAEA;
  margin: 20px 0;
}
.bfusion-landing__metadata {
  font-size: 10.5px;
  color: #8C8C8C;
  margin-bottom: 4px;
  font-weight: 400;
  line-height: 1.4;
}
.bfusion-landing__metadata strong {
  font-weight: 600;
  color: #707070;
}
/* ========================================================================== */
/* License Badge & Watermark                                                  */
/* ========================================================================== */
.bfusion-license-badge-wrap {
  position: absolute;
  bottom: 4px;
  left: 8px;
  z-index: 20;
  pointer-events: none;
}
.bfusion-license-badge {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  padding: 3px 10px;
  border-radius: 4px;
  font-size: 9px;
  font-family: "Segoe UI", wf_segoe-ui_normal, helvetica, arial, sans-serif;
  line-height: 1.3;
  pointer-events: auto;
  max-width: 380px;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.bfusion-license-badge--valid {
  background: rgba(5, 150, 105, 0.08);
  border: 1px solid rgba(5, 150, 105, 0.25);
  color: #059669;
}
.bfusion-license-badge--invalid {
  background: rgba(220, 38, 38, 0.06);
  border: 1px solid rgba(220, 38, 38, 0.2);
  color: #DC2626;
}
.bfusion-license-badge__icon {
  font-size: 11px;
  flex-shrink: 0;
}
.bfusion-license-badge__text {
  overflow: hidden;
  text-overflow: ellipsis;
}
.bfusion-license-badge__text strong {
  font-weight: 600;
}
.bfusion-watermark {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  z-index: 50;
  pointer-events: none;
  display: flex;
  align-items: center;
  justify-content: center;
  background: repeating-linear-gradient(-45deg, transparent, transparent 120px, rgba(220, 38, 38, 0.03) 120px, rgba(220, 38, 38, 0.03) 122px);
}
.bfusion-watermark__content {
  text-align: center;
  opacity: 0.18;
  user-select: none;
  transform: rotate(-18deg);
}
.bfusion-watermark__title {
  font-size: 56px;
  font-weight: 900;
  color: #DC2626;
  letter-spacing: 12px;
  line-height: 1;
  font-family: "Segoe UI", sans-serif;
}
.bfusion-watermark__subtitle {
  font-size: 16px;
  font-weight: 600;
  color: #DC2626;
  margin-top: 6px;
  letter-spacing: 3px;
  text-transform: uppercase;
  font-family: "Segoe UI", sans-serif;
}
.bfusion-watermark__link {
  font-size: 11px;
  color: #9CA3AF;
  margin-top: 12px;
  font-family: "Segoe UI", sans-serif;
}
/* ========================================================================== */
/* Plan Name Bar                                                               */
/* ========================================================================== */
.bfusion-plan-bar {
  display: flex;
  align-items: center;
  padding: 6px 14px;
  background: #F8F9FA;
  border-bottom: 1px solid #E0E4E8;
  min-height: 32px;
  flex-shrink: 0;
}
.bfusion-plan-bar__name {
  font-size: 13px;
  font-weight: 700;
  color: #1A202C;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
/* ========================================================================== */
/* Search Bar                                                                  */
/* ========================================================================== */
.bfusion-search-bar {
  position: absolute;
  top: 8px;
  left: 8px;
  z-index: 10;
  display: flex;
  align-items: center;
}
.bfusion-search-input {
  width: 200px;
  padding: 5px 10px;
  font-size: 11px;
  font-family: "Segoe UI", wf_segoe-ui_normal, helvetica, arial, sans-serif;
  border: 1px solid #CBD5E0;
  border-radius: 4px;
  background: rgba(255, 255, 255, 0.95);
  color: #333;
  outline: none;
  box-shadow: 0 1px 4px rgba(0, 0, 0, 0.06);
  transition: border-color 0.15s ease, box-shadow 0.15s ease;
}
.bfusion-search-input::placeholder {
  color: #A0AEC0;
}
.bfusion-search-input:focus {
  border-color: #1565C0;
  box-shadow: 0 0 0 2px rgba(21, 101, 192, 0.15);
}
/* ========================================================================== */
/* Zoom Toolbar                                                                */
/* ========================================================================== */
.bfusion-zoom-toolbar {
  position: absolute;
  bottom: 30px;
  right: 8px;
  z-index: 10;
  display: flex;
  flex-direction: column;
  gap: 2px;
  background: rgba(255, 255, 255, 0.95);
  border: 1px solid #E0E4E8;
  border-radius: 6px;
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.08);
  padding: 3px;
}
.bfusion-zoom-btn {
  width: 28px;
  height: 28px;
  border: none;
  border-radius: 4px;
  background: transparent;
  color: #4A5568;
  font-size: 14px;
  font-weight: 600;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  transition: background 0.12s ease;
  font-family: "Segoe UI", wf_segoe-ui_normal, helvetica, arial, sans-serif;
  padding: 0;
  line-height: 1;
}
.bfusion-zoom-btn:hover {
  background: #EDF2F7;
  color: #1A202C;
}
.bfusion-zoom-btn:active {
  background: #E2E8F0;
}
/* ========================================================================== */
/* Minimap                                                                     */
/* ========================================================================== */
.bfusion-minimap {
  position: absolute;
  bottom: 30px;
  left: 8px;
  z-index: 10;
  border: 1px solid #E0E4E8;
  border-radius: 6px;
  overflow: hidden;
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.08);
  background: #F8F9FA;
  cursor: crosshair;
}
/* ========================================================================== */
/* What-If Controls (Insights Panel)                                           */
/* ========================================================================== */
.bfusion-ip-whatif-controls {
  display: inline-flex;
  align-items: center;
  gap: 4px;
}
.bfusion-ip-whatif-btn {
  width: 22px;
  height: 22px;
  border: 1px solid #CBD5E0;
  border-radius: 3px;
  background: #FFFFFF;
  color: #4A5568;
  font-size: 13px;
  font-weight: 700;
  cursor: pointer;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 0;
  line-height: 1;
  transition: background 0.1s ease, border-color 0.1s ease;
  font-family: "Segoe UI", wf_segoe-ui_normal, helvetica, arial, sans-serif;
}
.bfusion-ip-whatif-btn:hover {
  background: #EDF2F7;
  border-color: #A0AEC0;
}
.bfusion-ip-whatif-btn:active {
  background: #E2E8F0;
}
.bfusion-ip-whatif-analyze {
  display: block;
  width: 100%;
  margin-top: 8px;
  padding: 6px 10px;
  border: none;
  border-radius: 4px;
  background: #6A1B9A;
  color: #FFFFFF;
  font-size: 10.5px;
  font-weight: 600;
  cursor: pointer;
  font-family: "Segoe UI", wf_segoe-ui_normal, helvetica, arial, sans-serif;
  transition: background 0.15s ease;
  letter-spacing: 0.3px;
}
.bfusion-ip-whatif-analyze:hover {
  background: #7B1FA2;
}
.bfusion-ip-whatif-analyze:active {
  background: #4A148C;
}
/* ========================================================================== */
/* Tooltip: Warning badge                                                      */
/* ========================================================================== */
.bfusion-tt-badge--warn {
  background: rgba(255, 109, 0, 0.08);
  color: #FF6D00;
}
/* ========================================================================== */
/* Drill-through / Actions Button (Insights Panel)                            */
/* ========================================================================== */
.bfusion-ip-drillthrough-btn {
  display: inline-block;
  margin-top: 8px;
  padding: 4px 12px;
  border: 1px solid #CBD5E0;
  border-radius: 4px;
  background: #FFFFFF;
  color: #4A5568;
  font-size: 10px;
  font-weight: 600;
  cursor: pointer;
  font-family: "Segoe UI", wf_segoe-ui_normal, helvetica, arial, sans-serif;
  transition: background 0.12s ease, border-color 0.12s ease;
  letter-spacing: 0.3px;
}
.bfusion-ip-drillthrough-btn:hover {
  background: #EDF2F7;
  border-color: #A0AEC0;
  color: #1A202C;
}
.bfusion-ip-drillthrough-btn:active {
  background: #E2E8F0;
}
/* ========================================================================== */
/* Print-optimized Layout                                                      */
/* ========================================================================== */
@media print {
  .bfusion-root {
    overflow: visible !important;
  }
  .bfusion-zoom-toolbar,
  .bfusion-minimap,
  .bfusion-search-bar,
  .bfusion-watermark,
  .bfusion-license-badge-wrap,
  .bfusion-tooltip {
    display: none !important;
  }
  .bfusion-chart-wrap {
    overflow: visible !important;
    height: auto !important;
  }
  .bfusion-chart-wrap svg {
    width: 100% !important;
    height: auto !important;
  }
  .bfusion-insights-panel {
    page-break-before: always;
    overflow: visible !important;
    height: auto !important;
    border-left: none;
  }
  .bfusion-main-area {
    flex-direction: column;
    height: auto !important;
    overflow: visible !important;
  }
}
/* ========================================================================== */
/* Empty Data State (cross-filter excluded everything)                        */
/* ========================================================================== */
.bfusion-empty {
  display: flex;
  width: 100%;
  height: 100%;
  align-items: center;
  justify-content: center;
  padding: 20px 24px 28px 24px;
  box-sizing: border-box;
}
.bfusion-empty__message {
  font-size: 12px;
  color: #94a3b8;
  font-weight: 400;
  text-align: center;
  letter-spacing: 0.2px;
}
